-- =============================================================================
-- PayPilot AI — Flyway Migration V1: Initial Schema
-- Database: paypilot_ai | MySQL 8.0.45
-- =============================================================================
-- SAFETY: All tables use CREATE TABLE IF NOT EXISTS.
-- Existing data is preserved. This migration is idempotent for fresh databases.
-- DO NOT edit this file after it has been applied to any environment.
-- Create a new V2__ migration file for schema changes.
-- =============================================================================

-- -------------------------------------------------------------------------
-- users
-- Minimal auth for hackathon MVP. Email + hashed password only.
-- No PII beyond what is strictly necessary.
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id          BIGINT          NOT NULL AUTO_INCREMENT,
    email       VARCHAR(255)    NOT NULL,
    name        VARCHAR(255)    NOT NULL,
    password_hash VARCHAR(255)  NOT NULL,
    role        VARCHAR(50)     NOT NULL DEFAULT 'USER',  -- USER | ADMIN
    created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
-- invoices
-- Core invoice records. Status managed exclusively by backend logic.
-- paypal_invoice_id: set when invoice is synced to PayPal Invoicing API.
-- Status PAID only set after verified PayPal capture (see payments table).
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invoices (
    id                  BIGINT          NOT NULL AUTO_INCREMENT,
    user_id             BIGINT          NOT NULL,
    paypal_invoice_id   VARCHAR(255)    NULL,       -- set after PayPal sync
    invoice_number      VARCHAR(100)    NOT NULL,
    client_name         VARCHAR(255)    NOT NULL,
    client_email        VARCHAR(255)    NOT NULL,
    description         TEXT            NULL,
    amount              DECIMAL(15, 2)  NOT NULL,
    currency            VARCHAR(10)     NOT NULL DEFAULT 'USD',
    status              VARCHAR(50)     NOT NULL DEFAULT 'DRAFT',
    -- Allowed statuses: DRAFT | SENT | PAID | OVERDUE | CANCELLED
    -- PAID is only set when payments.status = CAPTURED (verified PayPal response)
    due_date            DATE            NULL,
    issued_at           DATE            NULL,
    paid_at             DATETIME        NULL,
    -- AI extraction metadata
    ai_extracted        BOOLEAN         NOT NULL DEFAULT FALSE,
    ai_confidence       DECIMAL(5, 4)   NULL,       -- 0.0000 to 1.0000
    created_at          DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_invoices_number_user (invoice_number, user_id),
    INDEX idx_invoices_user_id (user_id),
    INDEX idx_invoices_status (status),
    INDEX idx_invoices_paypal_id (paypal_invoice_id),
    CONSTRAINT fk_invoices_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
-- payments
-- PayPal payment records. All fields sourced from actual PayPal API responses.
-- COMPLIANCE: Invoice PAID status is only set when this record status = CAPTURED
-- and paypal_capture_id is populated from a verified PayPal capture response.
--
-- Data stored: only what is necessary to verify and audit payment.
-- NOT stored: card numbers, bank details, full PayPal payer PII.
-- paypal_response_summary: truncated key fields only (not full raw response)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payments (
    id                      BIGINT          NOT NULL AUTO_INCREMENT,
    invoice_id              BIGINT          NOT NULL,
    paypal_order_id         VARCHAR(255)    NOT NULL,   -- from PayPal Orders API
    paypal_capture_id       VARCHAR(255)    NULL,       -- set after capture
    amount                  DECIMAL(15, 2)  NOT NULL,
    currency                VARCHAR(10)     NOT NULL DEFAULT 'USD',
    status                  VARCHAR(50)     NOT NULL DEFAULT 'CREATED',
    -- Allowed statuses: CREATED | APPROVED | CAPTURED | FAILED | CANCELLED
    -- CAPTURED: verified, paypal_capture_id populated, invoice marked PAID
    paypal_response_summary JSON            NULL,
    -- Stores key verification fields only: order_id, capture_id, status, amount, currency
    -- Does NOT store: payer details, card info, or full raw responses
    captured_at             DATETIME        NULL,
    created_at              DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at              DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    INDEX idx_payments_invoice_id (invoice_id),
    INDEX idx_payments_order_id (paypal_order_id),
    INDEX idx_payments_capture_id (paypal_capture_id),
    CONSTRAINT fk_payments_invoice FOREIGN KEY (invoice_id) REFERENCES invoices (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
-- audit_logs
-- Immutable record of all important financial and system events.
-- actor: USER (human), AI_AGENT (AI-proposed, human-approved), SYSTEM (automated)
-- This table is append-only. No UPDATE or DELETE should ever be issued against it.
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_logs (
    id              BIGINT          NOT NULL AUTO_INCREMENT,
    user_id         BIGINT          NULL,           -- NULL for system events
    entity_type     VARCHAR(100)    NOT NULL,       -- e.g. INVOICE, PAYMENT, USER
    entity_id       BIGINT          NULL,
    action          VARCHAR(100)    NOT NULL,       -- e.g. INVOICE_CREATED, PAYMENT_CAPTURED
    actor           VARCHAR(50)     NOT NULL,       -- USER | AI_AGENT | SYSTEM
    details         JSON            NULL,           -- non-sensitive context
    ip_address      VARCHAR(45)     NULL,
    created_at      DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    INDEX idx_audit_user_id (user_id),
    INDEX idx_audit_entity (entity_type, entity_id),
    INDEX idx_audit_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------------------
-- ai_extraction_logs
-- Transparency record for every AI invoice extraction operation.
-- Required for hackathon AI disclosure and audit trail.
-- Tracks model used, confidence score, and whether the user confirmed the output.
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_extraction_logs (
    id                  BIGINT          NOT NULL AUTO_INCREMENT,
    invoice_id          BIGINT          NULL,       -- set after user confirms and invoice is saved
    model_used          VARCHAR(100)    NOT NULL,   -- e.g. gpt-4o
    prompt_tokens       INT             NULL,
    completion_tokens   INT             NULL,
    confidence_score    DECIMAL(5, 4)   NULL,
    validated_by_user   BOOLEAN         NOT NULL DEFAULT FALSE,
    -- true only after user explicitly confirms the extracted data
    extraction_method   VARCHAR(50)     NOT NULL DEFAULT 'TEXT',
    -- TEXT: pdfjs text extraction | OCR: future Tesseract path
    created_at          DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    INDEX idx_ai_logs_invoice_id (invoice_id),
    CONSTRAINT fk_ai_logs_invoice FOREIGN KEY (invoice_id) REFERENCES invoices (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

